"""Build the public RenderFormer pages from local measured results."""
from pathlib import Path
import html,json,shutil

R=Path(__file__).resolve().parents[1];D=R/'docs';A=D/'assets/course-control'
A.mkdir(exist_ok=True)
source=R.parent/'showcase/bistro-cornell'
for name in ['cornell-control.png','cornell-reference.png','cornell-pretrained.png','cornell-error.png','cornell-measurements.json']:
    shutil.copyfile(source/name,A/name)
F=D/'assets/references';F.mkdir(exist_ok=True)
for name in ['beauty.png','direct.png','indirect.png','emission.png','environment.png','settings.json','pass-validation.json']:
    shutil.copyfile(R.parent/'experiments/sponza/reference'/name,F/name)
shutil.copyfile(R.parent/'experiments/cornell/reference.png',F/'cornell.png')
shutil.copyfile(R.parent/'experiments/cornell/parameters.json',F/'cornell-parameters.json')
M=json.loads((A/'cornell-measurements.json').read_text())
E=D/'assets/course-training'
metrics=[json.loads((E/label/'metrics.json').read_text()) for label in ['initial','pretrained','step-00500','step-02000','step-04000','step-06000','step-08000','step-10000']]
latest=metrics[-1]
(D/'study-status.json').write_text(json.dumps(dict(scope=['official pretrained inference','Cornell-family training','native Sponza reference'],formal_training_started=True,training_stage='paused_hardware_failure',validation_report='course-training.html',final_test_evaluated=False),indent=2))
